local __pte_b64=""
local __pte_key="UFRFMjktZml4ZWQtcnVudGltZS1rZXktN0YzQTlDMkQ="
local __pte_alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function __pte_b64decode(s)
    s=s:gsub("[^%w%+%/%=]","")
    local out,buffer,bits={},0,0
    for i=1,#s do
        local c=s:sub(i,i)
        if c~="=" then
            local n=__pte_alphabet:find(c,1,true)
            if n then
                buffer=buffer*64+n-1
                bits=bits+6
                if bits>=8 then
                    bits=bits-8
                    out[#out+1]=string.char(math.floor(buffer/2^bits)%256)
                    buffer=buffer%(2^bits)
                end
            end
        end
    end
    return table.concat(out)
end
local function __pte_xor(a,b)
    local r,bit=0,1
    while a>0 or b>0 do
        if (a%2)~=(b%2) then r=r+bit end
        a=math.floor(a/2); b=math.floor(b/2); bit=bit*2
    end
    return r
end
local function __pte_decrypt(data,key)
    local out={}
    for i=1,#data do out[i]=string.char(__pte_xor(data:byte(i),key:byte((i-1)%#key+1))) end
    return table.concat(out)
end
local __pte_source=__pte_decrypt(__pte_b64decode(__pte_b64),__pte_b64decode(__pte_key))
local __pte_chunk,__pte_error=loadstring(__pte_source,"@PalenationToolExtended")
if not __pte_chunk then error("[PTE] compile error: "..tostring(__pte_error)) end
local __pte_ok,__pte_runtime_error=pcall(__pte_chunk)
__pte_source=nil; __pte_b64=nil; __pte_key=nil
if not __pte_ok then error("[PTE] runtime error: "..tostring(__pte_runtime_error)) end
